import React, { useEffect, useState } from "react";
import axios from "axios";
import {
  FaCalendarAlt,
  FaPlusCircle,
  FaClock,
  FaCheckCircle,
  FaExclamationTriangle
} from "react-icons/fa";
import AppShell from "./ui/AppShell";
import Panel from "./ui/Panel";
import AlertBox from "./AlertBox";
import "./theme.css";

function Planner() {
  const userId = localStorage.getItem("user_id");

  const [plans, setPlans] = useState([]);
  const [courses, setCourses] = useState([]);
  const [alert, setAlert] = useState(null);

  const [form, setForm] = useState({
    course_id: "",
    study_date: "",
    topic: ""
  });

  const loadData = async () => {
    try {
      const p = await axios.get(`http://127.0.0.1:8000/planner/${userId}`);
      setPlans(p.data.plans || []);

      const c = await axios.get("http://127.0.0.1:8000/courses");
      const e = await axios.get(`http://127.0.0.1:8000/enrollments/${userId}`);
      const enrolledIds = e.data.map((x) => x.course_id);

      setCourses(
        (c.data.courses || []).filter((course) =>
          enrolledIds.includes(course.id)
        )
      );
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleAdd = async (e) => {
    e.preventDefault();

    if (!form.course_id || !form.study_date || !form.topic) {
      setAlert({ message: "Please fill all plan details", type: "error" });
      return;
    }

    try {
      const res = await axios.post("http://127.0.0.1:8000/create-plan", {
        user_id: parseInt(userId),
        course_id: parseInt(form.course_id),
        study_date: form.study_date,
        topic: form.topic
      });

      setAlert({ message: res.data.message || "Plan created", type: "success" });
      setForm({ course_id: "", study_date: "", topic: "" });
      loadData();
    } catch (err) {
      console.error(err);
      setAlert({ message: "Plan creation failed", type: "error" });
    }
  };

  const today = new Date(new Date().toDateString());

  const pendingCount = plans.filter((p) => p.status === "Pending").length;
  const completedCount = plans.filter((p) => p.status === "Completed").length;
  const expiredCount = plans.filter(
    (p) => p.status === "Expired" || new Date(p.study_date) < today
  ).length;

  const getCourseName = (courseId) => {
    const c = courses.find((x) => Number(x.id) === Number(courseId));
    return c ? c.title : `Course ${courseId}`;
  };

  return (
    <AppShell
      title="Study Planner"
      subtitle="Create manual study plans and track daily learning tasks."
      action={
        <span className="badge badge-purple">
          <FaCalendarAlt />
          Manual Planner
        </span>
      }
    >
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <div className="page-grid-4" style={{ marginBottom: "20px" }}>
        <div className="stat-card">
          <div className="dashboard-icon">
            <FaCalendarAlt />
          </div>
          <div className="stat-label">Total Plans</div>
          <div className="stat-value">{plans.length}</div>
          <div className="muted">All created study plans</div>
        </div>

        <div className="stat-card">
          <div className="dashboard-icon info">
            <FaClock />
          </div>
          <div className="stat-label">Pending</div>
          <div className="stat-value">{pendingCount}</div>
          <div className="muted">Plans waiting for action</div>
        </div>

        <div className="stat-card">
          <div className="dashboard-icon success">
            <FaCheckCircle />
          </div>
          <div className="stat-label">Completed</div>
          <div className="stat-value">{completedCount}</div>
          <div className="muted">Finished learning tasks</div>
        </div>

        <div className="stat-card">
          <div className="dashboard-icon warning">
            <FaExclamationTriangle />
          </div>
          <div className="stat-label">Expired</div>
          <div className="stat-value">{expiredCount}</div>
          <div className="muted">Overdue plans</div>
        </div>
      </div>

      <div className="page-grid-2">
        <Panel title="Create Study Plan">
          <form onSubmit={handleAdd}>
            <select
              className="select"
              value={form.course_id}
              onChange={(e) => setForm({ ...form, course_id: e.target.value })}
            >
              <option value="">Select Course</option>
              {courses.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.title} ({c.subject_code})
                </option>
              ))}
            </select>

            <input
              type="date"
              className="input"
              value={form.study_date}
              onChange={(e) => setForm({ ...form, study_date: e.target.value })}
              style={{ marginTop: "12px" }}
            />

            <input
              className="input"
              placeholder="Topic / Task"
              value={form.topic}
              onChange={(e) => setForm({ ...form, topic: e.target.value })}
              style={{ marginTop: "12px" }}
            />

            <button className="btn btn-primary" style={{ marginTop: "14px" }}>
              <FaPlusCircle />
              Add Plan
            </button>
          </form>
        </Panel>

        <Panel title="Your Plans">
          {plans.length === 0 ? (
            <div className="empty-state">
              <FaCalendarAlt />
              <h3>No plans found</h3>
              <p className="muted">Create a plan to start organizing your study routine.</p>
            </div>
          ) : (
            <div className="planner-list">
              {plans.map((p) => {
                const isExpired = new Date(p.study_date) < today;
                const status =
                  p.status === "Completed"
                    ? "Completed"
                    : isExpired
                    ? "Expired"
                    : "Pending";

                return (
                  <div className="planner-card" key={p.id}>
                    <div className="planner-date">
                      <FaCalendarAlt />
                      <span>{p.study_date}</span>
                    </div>

                    <h4>{p.topic}</h4>
                    <p className="muted">{getCourseName(p.course_id)}</p>

                    <span
                      className={
                        status === "Completed"
                          ? "badge badge-green"
                          : status === "Expired"
                          ? "badge badge-red"
                          : "badge badge-purple"
                      }
                    >
                      {status}
                    </span>
                  </div>
                );
              })}
            </div>
          )}
        </Panel>
      </div>
    </AppShell>
  );
}

export default Planner;
